command:
$ErrorActionPreference = 'Stop'
Set-Location 'C:\Users\koval\Documents\ZolotyayLopata'
$Host.UI.RawUI.WindowTitle = 'Premarket: offline sampling quality, no network'
$log = 'docs\analysis\premarket-depth-sampling-20261005\visible-audit.log'
try {
    Write-Host 'OFFLINE ONLY. Stop: Ctrl+C. Limit: 300 sec. No market data writer.'
    Write-Host 'Status: Get-Content docs\analysis\premarket-depth-sampling-20261005\visible-audit.log -Tail 20'
    & 'C:\Program Files\Python313\python.exe' trading_mvp\src\premarket_depth_sampling_protocol.py --repo-root . --protocol docs\plans\premarket-depth-sampling-protocol-20261005-v1.json --freeze-only 2>&1 | Tee-Object -FilePath $log
    if ($LASTEXITCODE -ne 0) { throw 'Protocol freeze failed' }
    & 'C:\Program Files\Python313\python.exe' trading_mvp\src\premarket_depth_sampling_protocol.py --repo-root . --protocol docs\plans\premarket-depth-sampling-protocol-20261005-v1.json --output docs\analysis\premarket-depth-sampling-20261005\sampling-quality-v1.json 2>&1 | Tee-Object -FilePath $log -Append
    if ($LASTEXITCODE -ne 0) { throw 'Quality audit failed' }
    'OFFLINE_AUDIT_COMPLETE_NO_COLLECTOR' | Tee-Object -FilePath $log -Append
} catch {
    ('OFFLINE_AUDIT_FAILED: ' + $_.Exception.Message) | Tee-Object -FilePath $log -Append
    Write-Host $_ -ForegroundColor Red
}
